/** A streamed answer did not pass its grounding check. Clients remove it. */
export interface AnswerRetracted {
  seq: number;
  ts: number;
  turn_id: string | null;
  type: "answer.retracted";
  reason: string;
}

/** The final text of the turn. Clients show it in place of whatever they streamed. When `held` is true no deltas went out before it. */
export interface AssistantMessage {
  seq: number;
  ts: number;
  turn_id: string | null;
  type: "assistant.message";
  text: string;
  held: boolean;
  hits: RetrievalHit[];
}

